from PIL import Image
from email.parser import BytesParser
from email import policy

IDS = {
 'A_Sugar': '09R8_2nJtjg',
 'B_Senorita': 'Pkh8UtuejGw',
 'C_Roar': 'CevxZvSJLk8',
 'D_Hello': 'YQHsXMglC9A',
 'E_BillieJean': 'Zi_XLOBDo_Y',
 'F_LazySong': 'fLexgOxsZu0',
 'G_Starboy': '34Na4j8AVgA',
 'H_NewRules': 'k2qgadSvNyU',
 'I_Sorry': 'fRh_vgS2dFE',
 'J_Rude': 'PIh2xe4jNkM',
}

def get_info(vid):
    opts = {'skip_download': True, 'quiet': True, 'noplaylist': True}
    with yt_dlp.YoutubeDL(opts) as y:
        return y.extract_info(f'https://www.youtube.com/watch?v={vid}', download=False)

def download_storyboard(vid, fmt):
    out = f'/tmp/sb_{vid}_{fmt}'
    if os.path.exists(out):
        return out
    opts = {'format': fmt, 'outtmpl': out, 'quiet': True, 'noplaylist': True}
    with yt_dlp.YoutubeDL(opts) as y:
        y.download([f'https://www.youtube.com/watch?v={vid}'])
    return out

def parse_mime(path):
    with open(path, 'rb') as f:
        msg = BytesParser(policy=policy.default).parse(f)
    parts = []
    for part in msg.iter_parts():
        if part.get_content_type().startswith('image'):
            parts.append(part.get_payload(decode=True))
    return parts

def grid_mean(im, cols, rows, count):
    tw, th = im.width // cols, im.height // rows
    frames = []
    for r in range(rows):
        for c in range(cols):
            if len(frames) >= count:
                break
            cell = im.crop((c * tw + 2, r * th + 2, (c + 1) * tw - 2, (r + 1) * th - 2))
            small = cell.resize((6, 6))
            px = small.load()
            rr = gg = bb = 0
            for yy in range(6):
                for xx in range(6):
                    p = px[xx, yy]
                    rr += p[0]; gg += p[1]; bb += p[2]
            frames.append((rr / 36, gg / 36, bb / 36))
    return frames

results = {}
for key, vid in IDS.items():
    try:
        info = get_info(vid)
        dur = info['duration']
        title = info.get('title')
        sbf = [f for f in info['formats'] if f.get('format_id', '').startswith('sb')]
        if not sbf:
            print(key, title, dur, 'NO SB FORMAT')
            continue
        # pick the sb with the largest height
        best = max(sbf, key=lambda f: (f.get('height') or 0))
        fid = best['format_id']
        meta = {k: best.get(k) for k in ('format_id', 'width', 'height', 'columns', 'rows', 'framecount', 'duration', 'fps', 'format_note')}
        path = download_storyboard(vid, fid)
        mosaics = parse_mime(path)
        cols = best.get('columns'); rows = best.get('rows')
        count = best.get('framecount') or best.get('frames') or (cols * rows * len(mosaics))
        frames = []
        for m in mosaics:
            im = Image.open(io.BytesIO(m)).convert('RGB')
            frames += grid_mean(im, cols, rows, count)
        print(f"{key} | {title} | dur={dur}s | sb={fid} {best.get('width')}x{best.get('height')} cols={cols} rows={rows} count={count} mosaics={len(mosaics)} frames={len(frames)}")
        results[key] = {'title': title, 'dur': dur, 'meta': meta, 'frames': frames}
    except Exception as e:
        print(key, 'ERROR', repr(e))

json.dump(results, open('sb_data.json', 'w'))
print('saved sb_data.json')

