import yt_dlp, json, io, re, os, math
from PIL import Image

IDS = {
 'A_Sugar': '09R8_2nJtjg',
 'B_Senorita': 'Pkh8UtuejGw',
 'C_Roar': 'CevxZvSJLk8',
 'D_Hello': 'YQHsXMglC9A',
 'E_BillieJean': 'Zi_XLOBDo_Y',
 'F_LazySong': 'fLexgOxsZu0',
 'G_Starboy': '34Na4j8AVgA',
 'H_NewRules': 'k2qgadSvNyU',
 'I_Sorry': 'fRh_vgS2dFE',
 'J_Rude': 'PIh2xe4jNkM',
}

def get_info(ydl, vid):
    return ydl.extract_info(f'https://www.youtube.com/watch?v={vid}', download=False)

def thumb_mean(img):
    small = img.resize((6, 6))
    px = small.load()
    rr = gg = bb = 0
    for yy in range(6):
        for xx in range(6):
            p = px[xx, yy]
            rr += p[0]; gg += p[1]; bb += p[2]
    return (rr / 36, gg / 36, bb / 36)

def decode_mosaic(data):
    im = Image.open(io.BytesIO(data))
    im.load()
    return im.convert('RGB')

def mosaic_frames(im, cols, rows, count):
    tw, th = im.width // cols, im.height // rows
    frames = []
    for r in range(rows):
        for c in range(cols):
            if len(frames) >= count:
                break
            cell = im.crop((c * tw + 2, r * th + 2, (c + 1) * tw - 2, (r + 1) * th - 2))
            frames.append(thumb_mean(cell))
    return frames

def main():
    ydl = yt_dlp.YoutubeDL({'quiet': True, 'noplaylist': True, 'no_warnings': True})
    out = {}
    for key, vid in IDS.items():
        try:
            info = get_info(ydl, vid)
        except Exception as e:
            print(key, 'INFO ERROR', repr(e)[:120])
            continue
        dur = info['duration']
        title = info.get('title')
        sbf = [f for f in info['formats'] if f.get('format_note') == 'storyboard']
        if not sbf:
            print(key, title, dur, 'NO SB')
            continue
        best = max(sbf, key=lambda f: (f.get('height') or 0))
        cols, rows = best['columns'], best['rows']
        frags = best.get('fragments') or [{'url': best['url']}]
        frames = []
        fails = 0
        for i, fr in enumerate(frags):
            url = fr['url'].replace('$M', f'M{i}')
            try:
                data = ydl.urlopen(url).read()
            except Exception as e:
                print('  ', key, 'frag', i, 'DL ERR', repr(e)[:80]); fails += 1; continue
            try:
                im = decode_mosaic(data)
            except Exception as e:
                # fallback: dwebp / magick
                import subprocess, tempfile
                try:
                    p = f'/tmp/frag_{vid}_{i}'
                    open(p, 'wb').write(data)
                    r = subprocess.run(['dwebp', p, '-o', p + '.png'], capture_output=True)
                    if r.returncode != 0:
                        r = subprocess.run(['convert', p, p + '.png'], capture_output=True)
                    im = Image.open(p + '.png').convert('RGB')
                except Exception as e2:
                    print('  ', key, 'frag', i, 'DECODE ERR', repr(e)[:60], repr(e2)[:60]); fails += 1; continue
            frames += mosaic_frames(im, cols, rows, cols * rows)
        n = len(frames)
        interval = dur / max(n, 1)
        print(f"{key} | {title} | dur={dur}s | {best['width']}x{best['height']} grid {cols}x{rows} frags={len(frags)} frames={n} interval={interval:.2f}s fails={fails}")
        out[key] = {'title': title, 'dur': dur, 'interval': interval, 'frames': frames}
    json.dump(out, open('sb_data.json', 'w'))
    print('saved sb_data.json')

main()

