def mosaic_frames(im, cols, rows, count):
    tw, th = im.width // cols, im.height // rows
    frames = []
    for r in range(rows):
        for c in range(cols):
            if len(frames) >= count:
                break
            cell = im.crop((c * tw + 2, r * th + 2, (c + 1) * tw - 2, (r + 1) * th - 2))
            frames.append(thumb_mean(cell))
    return frames

